// Check MCP resources for any rendering service, and test fetch reachability to local services.
const out = {};
try {
  out.mcp = await tools.opencode.list_mcp_resources();
} catch (e) {
  out.mcp = "ERROR: " + (e && e.message ? e.message : String(e));
}
// Test fetch to the local MCP server and model server
const probe = async (url) => {
  try {
    const r = await fetch(url, { method: "GET" });
    return { url, status: r.status, ok: r.ok };
  } catch (e) {
    return { url, error: e && e.message ? e.message : String(e) };
  }
};
out.probes = await Promise.all([
  probe("http://172.21.0.2:8181/mcp"),
  probe("http://172.21.0.1:8081/v1/models"),
]);
return out;

